#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31
#
# probe-permission-deny.sh (#3835): does a NATIVE permissions.deny rule block a
# Bash tool call, with NO ork hooks loaded, under --dangerously-skip-permissions
# (the mode the affected users actually run)? This is the tripwire the
# divergence purge stands on: every deleted guard assumed CC's own layer holds.
#
# Design: canary file. The stub model (zero spend) is scripted via STUB_TOOL_USE
# to request `touch <scratch>/canary-<arm>`. TRIP arm: settings deny that exact
# command prefix; the canary must NOT appear and the follow-up request must
# carry a denial-shaped tool_result. CONTROL arm: no deny rule; the canary MUST
# appear, proving the probe can observe execution at all (a probe that cannot
# see the fear come true measures nothing).
#
# Exit: 0 trip denied AND control executed
#       1 REGRESSED: the deny rule did not block (canary exists in trip arm).
#         Restore the deleted guard hooks from git history (#3835) before
#         shipping anything.
#       2 could-not-observe (claude/stub failed, control arm did not execute)
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CLAUDE_BIN="${CLAUDE_BIN:-claude}"
command -v "$CLAUDE_BIN" >/dev/null || { echo "COULD-NOT-OBSERVE: $CLAUDE_BIN not on PATH"; exit 2; }

SCRATCH="$(mktemp -d "${TMPDIR:-/tmp}/perm-deny-probe.XXXXXX")"
cleanup() {
  [ -n "${STUB_PID:-}" ] && kill "$STUB_PID" 2>/dev/null || true  # silent: post-cleanup
  [ "${SMOKE_KEEP:-0}" = "1" ] || rm -rf "$SCRATCH"
}
trap cleanup EXIT

run_arm() { # $1 arm-name  $2 settings-file
  local arm="$1" settings="$2" canary="$SCRATCH/canary-$1" fake_home="$SCRATCH/home-$1" port
  mkdir -p "$fake_home"
  STUB_LOG="$SCRATCH/requests-$arm.jsonl" STUB_PORT_FILE="$SCRATCH/port-$arm" \
    STUB_TOOL_USE="{\"name\":\"Bash\",\"input\":{\"command\":\"touch $canary\"}}" \
    STUB_GREP='denied|Permission|rejected|blocked' \
    node "$HERE/stub-anthropic-api.mjs" > "$SCRATCH/stub-$arm.log" 2>&1 &
  STUB_PID=$!
  for _ in $(seq 1 50); do [ -s "$SCRATCH/port-$arm" ] && break; sleep 0.1; done
  [ -s "$SCRATCH/port-$arm" ] || { echo "COULD-NOT-OBSERVE: stub did not start ($arm)"; exit 2; }
  port="$(cat "$SCRATCH/port-$arm")"

  set +e
  env -u CLAUDECODE -u CLAUDE_CODE_OAUTH_TOKEN -u CLAUDE_CONFIG_DIR \
    HOME="$fake_home" ANTHROPIC_BASE_URL="http://127.0.0.1:$port" ANTHROPIC_API_KEY="perm-deny-probe" \
    DISABLE_TELEMETRY=1 DISABLE_ERROR_REPORTING=1 \
    "$CLAUDE_BIN" -p "run the command" --settings "$settings" \
      --dangerously-skip-permissions --output-format json --max-turns 2 \
      > "$SCRATCH/result-$arm.json" 2> "$SCRATCH/stderr-$arm.txt" < /dev/null
  local rc=$?
  set -e
  kill "$STUB_PID" 2>/dev/null || true  # silent: post-cleanup
  STUB_PID=""
  echo "$arm: claude rc=$rc canary=$([ -e "$canary" ] && echo EXISTS || echo absent)"
}

# CONTROL: empty settings; the scripted touch must execute under bypass.
printf '{}\n' > "$SCRATCH/settings-control.json"
run_arm control "$SCRATCH/settings-control.json"
if [ ! -e "$SCRATCH/canary-control" ]; then
  echo "COULD-NOT-OBSERVE: control arm did not execute the canary; the probe cannot see execution."
  head -c 600 "$SCRATCH/stderr-control.txt" || true  # silent: best-effort
  exit 2
fi

# TRIP: deny the exact command prefix.
printf '{"permissions":{"deny":["Bash(touch %s)"]}}\n' "$SCRATCH/canary-trip" > "$SCRATCH/settings-trip.json"
run_arm trip "$SCRATCH/settings-trip.json"

DENIAL_SEEN="$(node -e '
const fs=require("fs");
let hit=false;
try{for(const l of fs.readFileSync(process.argv[1],"utf8").trim().split("\n")){const r=JSON.parse(l);if(r.grep_hit)hit=true;}}catch{}
process.stdout.write(String(hit));' "$SCRATCH/requests-trip.jsonl")"

if [ -e "$SCRATCH/canary-trip" ]; then
  echo "REGRESSED: permissions.deny did NOT block the Bash call under --dangerously-skip-permissions."
  echo "Restore the deleted guard hooks from git history (#3835) before relying on native rules."
  exit 1
fi
echo "PASS: trip canary absent (deny held under bypass); denial text seen by model: $DENIAL_SEEN"
exit 0
